(()=>{'use strict';
const RELEASE='20260905-IM1';
const dataPath=document.documentElement.dataset.dataPath||'assets/projects.json';
const baseDir=dataPath.replace(/projects\.json$/,'');
const paths={base:dataPath,refresh:`${baseDir}portfolio-refresh.json`,pricing:`${baseDir}pricing-review.json`,live:`${baseDir}live-release.json`};
const STATUS={V:'Established software',P:'Developed prototype',R:'Research stage'};
const POTENTIAL={VH:'Very high',H:'High',M:'Moderate',S:'Specialist'};
const SAFE=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const EUR=v=>new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number(v)||0);
const USD=(v,r)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format((Number(v)||0)*r);
async function load(path){const r=await fetch(`${path}?v=${RELEASE}`,{cache:'no-store'});if(!r.ok)throw new Error(`Unable to load portfolio data`);return r.json()}
function build(base,refresh,pricing,live){const merged=JSON.parse(JSON.stringify(base));for(const c of refresh.replacements||[]){const row=merged.a.find(x=>x[0]===c.id);if(row){row[2]=c.slug;row[3]=c.name;row[6]=c.summary}}const refs=new Set(merged.a.map(x=>x[1]));for(const row of refresh.additions||[])if(!refs.has(row[1]))merged.a.push(row);for(const c of live.replacements||[]){const row=merged.a.find(x=>x[0]===c.id);if(row){row[2]=c.slug;row[3]=c.name;row[6]=c.summary}}const prices=new Map((pricing.records||[]).map(x=>[x[0],x]));const assets=merged.a.map(row=>{const p=prices.get(row[0]);return{id:row[0],ref:row[1],slug:row[2],name:row[3],category:merged.c[row[4]],statusCode:row[5],status:STATUS[row[5]],ask:Number(p?.[1]||0),priceLow:Number(p?.[2]||0),priceHigh:Number(p?.[3]||0),potentialCode:row[9],potential:POTENTIAL[row[9]],route:merged.r[row[10]],externalUrl:row[11]||''}});for(const x of live.additions||[])assets.push({...x,status:STATUS[x.statusCode],potential:POTENTIAL[x.potentialCode],externalUrl:x.externalUrl||''});assets.sort((a,b)=>a.id-b.id);return assets}
function set(id,v){const e=document.getElementById(id);if(e)e.textContent=v}
function renderOverview(assets,live){set('asset-count',assets.length);set('established-count',assets.filter(x=>x.statusCode==='V').length);set('prototype-count',assets.filter(x=>x.statusCode==='P').length);set('research-count',assets.filter(x=>x.statusCode==='R').length);set('ask-total',EUR(live.expected.strategic_asking_reference));set('ask-total-usd',`≈ ${USD(live.expected.strategic_asking_reference,live.fx.rate)} USD`);set('range-total',`${EUR(live.expected.strategic_band[0])} – ${EUR(live.expected.strategic_band[1])}`);set('range-total-usd',`≈ ${USD(live.expected.strategic_band[0],live.fx.rate)} – ${USD(live.expected.strategic_band[1],live.fx.rate)} USD`)}
function renderSchedule(assets,live){const box=document.getElementById('portfolio-schedule');if(!box)return;const search=document.getElementById('search'),sort=document.getElementById('sort'),filters=document.getElementById('filters'),count=document.getElementById('result-count');let active='all';const defs=[['all','All assets'],['V','Established software'],['P','Developed prototypes'],['R','Research stage']];filters.innerHTML=defs.map(([v,l],i)=>`<button class="filter${i?'':' active'}" type="button" data-filter="${v}">${l}</button>`).join('');filters.addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;active=b.dataset.filter;filters.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));draw()});function draw(){const q=(search?.value||'').trim().toLowerCase();const rows=assets.filter(a=>(active==='all'||a.statusCode===active)&&(!q||`${a.ref} ${a.name} ${a.category} ${a.route}`.toLowerCase().includes(q)));const mode=sort?.value||'ask-desc';if(mode==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));else if(mode==='ask-asc')rows.sort((a,b)=>a.ask-b.ask);else if(mode==='newest')rows.sort((a,b)=>b.id-a.id);else rows.sort((a,b)=>b.ask-a.ask);box.innerHTML=`<div class="schedule-row schedule-head"><span>Ref.</span><span>Asset</span><span>Commercial area</span><span>Stage</span><span>Potential</span><span style="text-align:right">Indicative ask</span></div>`+rows.map(a=>`<div class="schedule-row"><span>${SAFE(a.ref)}</span><strong><a href="projects/${SAFE(a.slug)}/">${SAFE(a.name)}</a></strong><span>${SAFE(a.category)}</span><span><span class="status">${SAFE(a.status)}</span></span><span>${SAFE(a.potential)}</span><span class="price">${EUR(a.ask)}<br><small>≈ ${USD(a.ask,live.fx.rate)}</small></span></div>`).join('');if(count)count.textContent=`${rows.length} of ${assets.length} assets`}search?.addEventListener('input',draw);sort?.addEventListener('change',draw);draw()}
function renderDetail(assets,live){const root=document.getElementById('project');if(!root)return;const slug=location.pathname.split('/').filter(Boolean).at(-1)||'';const aliases={'systemic-absolute-topology':'continuum-state-integrity-platform','lewis-hybrid-llm-orchestrator':'resource-aware-hybrid-model-orchestration-platform','sentinelbio-verify':'biometric-systems-assurance-platform','agentic-engineering-control-plane':'evidence-governed-software-assurance-platform','best-of-github-agentic-engineering':'evidence-governed-software-assurance-platform','axiomcrypt':'modular-key-cryptanalysis-platform','shield-breaker-research':'protein-structure-evidence-qualification-platform','titan-evtol-research-platform':'electric-flight-systems-simulation-validation-platform','chimera-spectral-perception-system':'vision-evidence-governed-multimodal-perception-framework'};const a=assets.find(x=>x.slug===(aliases[slug]||slug));if(!a){root.innerHTML='<section class="shell detail-shell"><div class="panel"><h1>Asset not found</h1><a class="btn" href="../../portfolio.html">Return to portfolio</a></div></section>';return}document.title=`${a.name} — Information Memorandum`;const canon=document.querySelector('link[rel="canonical"]');if(canon)canon.href=`https://thearchitect-max.github.io/MyProjects/projects/${a.slug}/`;root.innerHTML=`<header><div class="shell nav"><a class="brand" href="../../"><span class="mark">TA</span><span class="brand-copy"><strong>THEARCHITECT_MAX</strong><span>Information Memorandum</span></span></a><nav class="nav-links"><a href="../../">Overview</a><a href="../../portfolio.html">Portfolio</a><a href="../../opportunity.html">Opportunity</a><a href="../../transaction.html">Transaction</a><a href="../../notice.html">Notice</a></nav></div></header><div class="shell detail-shell"><section class="detail-hero"><p class="eyebrow">Commercial asset profile · ${SAFE(a.ref)}</p><h1>${SAFE(a.name)}</h1><p class="lede">A portfolio asset positioned within ${SAFE(a.category)}, with a primary commercialisation route through ${SAFE(a.route)}.</p></section><section class="detail-grid"><article class="panel"><h3>Commercial profile</h3><div class="fact-list"><div class="fact"><span>Commercial area</span><strong>${SAFE(a.category)}</strong></div><div class="fact"><span>Portfolio stage</span><strong>${SAFE(a.status)}</strong></div><div class="fact"><span>Commercial potential</span><strong>${SAFE(a.potential)}</strong></div><div class="fact"><span>Primary route to market</span><strong>${SAFE(a.route)}</strong></div></div><p class="fine" style="margin-top:18px">This profile intentionally excludes implementation detail. Technical, legal and operational due diligence is transaction-stage information.</p></article><aside class="price-card"><small>Indicative strategic asking reference</small><strong>${EUR(a.ask)}</strong><p>≈ ${USD(a.ask,live.fx.rate)} USD</p><div class="rule" style="border-top:1px solid rgba(255,255,255,.2);margin:24px 0"></div><small>Indicative range</small><strong style="font-size:1.9rem">${EUR(a.priceLow)} – ${EUR(a.priceHigh)}</strong><p>Subject to transaction scope, diligence and definitive documentation.</p></aside></section><div class="actions"><a class="btn primary" href="../../portfolio.html">Return to portfolio schedule</a><a class="btn" href="../../transaction.html">Transaction overview</a></div></div><footer class="footer"><div class="shell footer-inner"><div><strong>THEARCHITECT_MAX</strong><br>Information Memorandum</div><div>Commercial overview · For discussion purposes only</div></div></footer>`}
async function init(){try{const [base,refresh,pricing,live]=await Promise.all([load(paths.base),load(paths.refresh),load(paths.pricing),load(paths.live)]);const assets=build(base,refresh,pricing,live);renderOverview(assets,live);renderSchedule(assets,live);renderDetail(assets,live)}catch(e){console.error(e);const box=document.getElementById('portfolio-schedule');if(box)box.innerHTML='<div class="panel">Portfolio information is temporarily unavailable.</div>'}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();})();